import { klona } from 'klona';
import { Schema, type Schema as StatData } from '../../schema';
import { type AssistantApiConfig, useAssistantApiStore } from './assistantApiStore';

const UPDATE_BLOCK_PATTERN = /<UpdateVariable>[\s\S]*?<\/UpdateVariable>/gi;
const CONTENT_BLOCK_PATTERN = /<contenttext>([\s\S]*?)<\/contenttext>/i;
const IMAGE_BLOCK_PATTERN = /<image[^>]*>[\s\S]*?<\/image>/gi;
const ALLOWED_MESSAGE_TYPES = new Set(['normal', 'regenerate', 'continue', 'swipe']);
const CORE_ENTRY_NAMES = ['世界快穿核心设定', '性癖倾向与世界生成规则', '叙事与快穿节奏'] as const;

const AUXILIARY_SYSTEM_PROMPT = `你是《世界快穿模拟器》的变量更新处理器。你不续写剧情，不替玩家行动，也不解释自己的工作。
当前变量快照发生在最新剧情之前。请根据玩家输入和已经发生的剧情，严格遵守给定变量规则生成增量更新。
只输出一个完整的 <UpdateVariable>...</UpdateVariable>，不要输出正文、Markdown代码围栏或额外说明。`;

class TargetMessageChangedError extends Error {}
class AssistantApiStoppedError extends Error {}

type PromptBundle = {
  worldContext: string;
  updatePrompt: string;
};

type PendingSession = {
  messageId: number;
  chatId: string;
};

let disposeRunner: (() => void) | null = null;
let pendingSession: PendingSession | null = null;
let pendingTimer: ReturnType<typeof setTimeout> | null = null;

function currentChatId(): string {
  return String(SillyTavern.getCurrentChatId());
}

function runtimeIsGenerating(): boolean {
  const tavern = SillyTavern as typeof SillyTavern & {
    isGenerating?: boolean;
    getContext?: () => { isGenerating?: boolean };
  };
  return Boolean(tavern.isGenerating || tavern.getContext?.()?.isGenerating);
}

function nativeSendButtonDisabled(): boolean {
  try {
    return Boolean(window.parent.document.querySelector<HTMLButtonElement>('#send_but')?.disabled);
  } catch {
    return false;
  }
}

function readAssistantMessage(messageId: number): ChatMessage {
  const message = getChatMessages(messageId, { role: 'all' })[0];
  if (!message || message.role !== 'assistant') {
    throw new TargetMessageChangedError(`目标 AI 楼层不存在或已经变化（第 ${messageId} 层）`);
  }
  return message;
}

function extractNarrative(raw: string): string {
  const wrappedContent = raw.match(CONTENT_BLOCK_PATTERN)?.[1];
  return (wrappedContent ?? raw)
    .replace(UPDATE_BLOCK_PATTERN, '')
    .replace(IMAGE_BLOCK_PATTERN, '')
    .replace(/<StatusPlaceHolderImpl\s*\/?>/gi, '')
    .replace(/<WorldSimulatorUI\s*\/?>/gi, '')
    .trim();
}

function extractUpdateBlock(raw: string): string | null {
  const match = raw.match(/<UpdateVariable>[\s\S]*?<\/UpdateVariable>/i);
  return match?.[0].trim() || null;
}

function mergeUpdateBlock(raw: string, updateBlock: string): string {
  const narrative = raw.replace(UPDATE_BLOCK_PATTERN, '').trimEnd();
  return narrative ? `${narrative}\n\n${updateBlock}` : updateBlock;
}

function generationResultText(result: Awaited<ReturnType<typeof generate>>): string {
  return typeof result === 'string' ? result : result.content;
}

function customApiConfig(api: AssistantApiConfig): CustomApiConfig {
  return {
    apiurl: api.apiurl,
    key: api.key,
    model: api.model,
    source: api.source === 'google' ? 'makersuite' : 'openai',
  };
}

async function readPromptBundle(): Promise<PromptBundle> {
  const worldbookName = getCharWorldbookNames('current').primary;
  if (!worldbookName) throw new Error('当前角色卡没有绑定主世界书');
  const entries = await getWorldbook(worldbookName);
  const rules = entries.find(entry => entry.name === '[mvu_update]变量更新规则');
  const format = entries.find(entry => entry.name === '[mvu_update]变量输出格式');
  if (!rules?.content || !format?.content) throw new Error('世界书中的变量更新规则或输出格式缺失');

  const worldContext = CORE_ENTRY_NAMES.map(name => entries.find(entry => entry.name === name)?.content)
    .filter((content): content is string => Boolean(content))
    .join('\n\n');
  return {
    worldContext,
    updatePrompt: `${rules.content}\n\n${format.content}\n\n请处理最新剧情造成的变量变化。只输出一次完整的 <UpdateVariable>，其中必须包含 <JSONPatch>合法 JSON 操作数组</JSONPatch>。`,
  };
}

function readPreviousUserMessage(messageId: number): ChatMessage | null {
  if (messageId <= 0) return null;
  const messages = getChatMessages(`0-${messageId - 1}`, { role: 'all' });
  return _.findLast(messages, message => message.role === 'user') ?? null;
}

async function requestUpdate(
  api: AssistantApiConfig,
  prompts: PromptBundle,
  statData: StatData,
  userMessage: ChatMessage | null,
  narrative: string,
  generationId: string,
): Promise<string> {
  const orderedContext: RolePrompt[] = [
    { role: 'system', content: AUXILIARY_SYSTEM_PROMPT },
    ...(prompts.worldContext ? [{ role: 'system' as const, content: prompts.worldContext }] : []),
    { role: 'user', content: `[当前变量快照]\n${JSON.stringify(statData, null, 2)}` },
    ...(userMessage ? [{ role: 'user' as const, content: `[玩家本轮输入]\n${userMessage.message}` }] : []),
    { role: 'assistant', content: `[已经发生的最新剧情]\n${narrative}` },
  ];
  const customApi = customApiConfig(api);
  const result = api.sendPreset
    ? await generate({
        generation_id: generationId,
        user_input: prompts.updatePrompt,
        should_stream: false,
        should_silence: false,
        custom_api: customApi,
        overrides: { chat_history: { with_depth_entries: false, prompts: orderedContext } },
      })
    : await generateRaw({
        generation_id: generationId,
        user_input: prompts.updatePrompt,
        should_stream: false,
        should_silence: false,
        custom_api: { ...customApi, temperature: 0.2 },
        ordered_prompts: [...orderedContext, 'user_input'],
      });
  const text = generationResultText(result);
  const updateBlock = extractUpdateBlock(text);
  if (!updateBlock) throw new Error('回复中没有完整的 <UpdateVariable>');
  return updateBlock;
}

function ensureTargetUnchanged(messageId: number, chatId: string, originalMessage: string) {
  if (currentChatId() !== chatId) throw new TargetMessageChangedError('辅助 API 运行期间聊天已经切换');
  if (getLastMessageId() !== messageId) throw new TargetMessageChangedError('辅助 API 运行期间出现了新的聊天消息');
  const current = readAssistantMessage(messageId);
  if (current.message !== originalMessage) throw new TargetMessageChangedError('辅助 API 运行期间目标楼层已经变化');
}

function readBaseMvuData(messageId: number): Mvu.MvuData {
  const direct = klona(Mvu.getMvuData({ type: 'message', message_id: messageId }));
  const targetAlreadyUpdated = extractUpdateBlock(readAssistantMessage(messageId).message) !== null;
  if (targetAlreadyUpdated && !_.isEmpty(_.get(direct, 'stat_data'))) return direct;

  const oldestMessageId = Math.max(0, messageId - 100);
  for (let previousMessageId = messageId - 1; previousMessageId >= oldestMessageId; previousMessageId--) {
    const previousMessage = getChatMessages(previousMessageId, { role: 'all' })[0];
    if (previousMessage?.role !== 'assistant') continue;
    const previous = klona(Mvu.getMvuData({ type: 'message', message_id: previousMessageId }));
    if (!_.isEmpty(_.get(previous, 'stat_data'))) {
      console.info(
        `[世界快穿模拟器][辅助API] 第 ${messageId} 层尚无变量底表，继承第 ${previousMessageId} 层作为更新基准`,
      );
      return previous;
    }
  }

  if (!_.isEmpty(_.get(direct, 'stat_data'))) {
    console.info(`[世界快穿模拟器][辅助API] 第 ${messageId} 层找不到历史底表，使用本层变量作为更新基准`);
    return direct;
  }

  const chatData = klona(Mvu.getMvuData({ type: 'chat' }));
  if (!_.isEmpty(_.get(chatData, 'stat_data'))) {
    console.info(`[世界快穿模拟器][辅助API] 第 ${messageId} 层尚无变量底表，继承聊天变量作为更新基准`);
    return chatData;
  }
  return direct;
}

type JsonPatchEntry = Record<string, unknown>;

function extractJsonArray(source: string): string | null {
  let start = -1;
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let index = 0; index < source.length; index++) {
    const character = source[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') {
      inString = true;
      continue;
    }
    if (character === '[') {
      if (depth === 0) start = index;
      depth++;
    } else if (character === ']' && depth > 0) {
      depth--;
      if (depth === 0 && start >= 0) return source.slice(start, index + 1);
    }
  }
  return null;
}

function readJsonPatch(candidate: string): JsonPatchEntry[] {
  const updateBlock = extractUpdateBlock(candidate) ?? candidate;
  const taggedSource = updateBlock.match(/<JSONPatch\b[^>]*>([\s\S]*?)<\/JSONPatch\s*>/i)?.[1]?.trim();
  const fallbackSource = extractJsonArray(
    updateBlock
      .replace(/<Analysis\b[^>]*>[\s\S]*?<\/Analysis\s*>/gi, '')
      .replace(/```(?:json)?/gi, '')
      .replace(/<\/?(?:UpdateVariable|JSONPatch)\b[^>]*>/gi, ''),
  );
  const source = taggedSource || fallbackSource;
  if (!source) throw new Error('辅助 API 回复中既没有 <JSONPatch>，也没有可识别的 JSON 操作数组');
  let parsed: unknown;
  try {
    parsed = JSON.parse(source);
  } catch (error) {
    throw new Error(`JSONPatch 不是合法 JSON：${error instanceof Error ? error.message : String(error)}`, {
      cause: error,
    });
  }
  if (!Array.isArray(parsed)) throw new Error('JSONPatch 必须是操作数组');
  return parsed.map((entry, index) => {
    if (!_.isPlainObject(entry)) throw new Error(`JSONPatch 第 ${index + 1} 项不是对象`);
    return entry as JsonPatchEntry;
  });
}

function decodeJsonPointer(pointer: unknown, label: string): string[] {
  let segments: string[];
  if (Array.isArray(pointer) && pointer.every(segment => typeof segment === 'string')) {
    segments = pointer;
  } else if (typeof pointer === 'string' && pointer.trim()) {
    const normalized = pointer.trim();
    if (normalized.startsWith('/')) {
      segments = normalized
        .slice(1)
        .split('/')
        .map(segment => segment.replaceAll('~1', '/').replaceAll('~0', '~'));
    } else if (normalized.includes('/')) {
      segments = normalized.split('/').map(segment => segment.replaceAll('~1', '/').replaceAll('~0', '~'));
    } else {
      // 兼容模型常见的 lodash/JSONPath 写法：当前世界.当前时间、$.主角.世界币、角色[0].姓名。
      segments = _.toPath(normalized);
    }
  } else {
    throw new Error(`${label} 必须是变量路径字符串或字符串数组`);
  }
  if (segments[0] === '$') segments.shift();
  if (segments[0]?.toLowerCase() === 'stat_data') segments.shift();
  if (!segments.length || segments.some(segment => !segment)) throw new Error(`${label} 不能指向变量根节点或空路径`);
  if (segments.some(segment => ['__proto__', 'prototype', 'constructor'].includes(segment))) {
    throw new Error(`${label} 包含不安全路径`);
  }
  if (segments.some(segment => segment.startsWith('$'))) throw new Error(`${label} 试图修改只读派生字段`);
  return segments;
}

function readArrayIndex(segment: string, length: number, allowEnd: boolean): number {
  if (allowEnd && segment === '-') return length;
  if (!/^\d+$/.test(segment)) throw new Error(`数组索引 ${segment} 无效`);
  const index = Number(segment);
  const upperBound = allowEnd ? length : length - 1;
  if (index < 0 || index > upperBound) throw new Error(`数组索引 ${segment} 越界`);
  return index;
}

function setAtPointer(root: object, segments: string[], value: unknown, insert: boolean): void {
  const parentPath = segments.slice(0, -1);
  const key = segments.at(-1)!;
  const parent = parentPath.length ? _.get(root, parentPath) : root;
  if (Array.isArray(parent)) {
    const index = readArrayIndex(key, parent.length, insert);
    if (insert) parent.splice(index, 0, klona(value));
    else parent[index] = klona(value);
    return;
  }
  if (!_.isPlainObject(parent)) throw new Error(`路径 /${segments.join('/')} 的父节点不存在或不是对象`);
  _.set(root, segments, klona(value));
}

function removeAtPointer(root: object, segments: string[]): unknown {
  const parentPath = segments.slice(0, -1);
  const key = segments.at(-1)!;
  const parent = parentPath.length ? _.get(root, parentPath) : root;
  if (Array.isArray(parent)) {
    const index = readArrayIndex(key, parent.length, false);
    return parent.splice(index, 1)[0];
  }
  if (!_.isPlainObject(parent) || !Object.hasOwn(parent, key)) {
    throw new Error(`路径 /${segments.join('/')} 不存在，无法删除`);
  }
  const value = _.get(root, segments);
  _.unset(root, segments);
  return value;
}

function applyJsonPatch(statData: StatData, operations: JsonPatchEntry[]): StatData {
  const next = klona(statData);
  operations.forEach((entry, index) => {
    const operation = typeof entry.op === 'string' ? entry.op.toLowerCase() : entry.op;
    const prefix = `JSONPatch 第 ${index + 1} 项`;
    if (typeof operation !== 'string') throw new Error(`${prefix} 缺少 op`);

    if (operation === 'move') {
      const from = decodeJsonPointer(entry.from, `${prefix}.from`);
      const to = decodeJsonPointer(entry.to ?? entry.path, `${prefix}.to`);
      if (_.isEqual(from, ['主角', '世界币']) || _.isEqual(to, ['主角', '世界币'])) {
        throw new Error(`${prefix} 不得移动或覆盖世界币`);
      }
      const value = removeAtPointer(next, from);
      setAtPointer(next, to, value, true);
      return;
    }

    const path = decodeJsonPointer(entry.path, `${prefix}.path`);
    const targetsCurrency = _.isEqual(path, ['主角', '世界币']);
    switch (operation) {
      case 'set':
      case 'replace':
        if (targetsCurrency) throw new Error(`${prefix} 不得整体覆盖世界币，只能用正数 delta 发放额外收入`);
        setAtPointer(next, path, entry.value, false);
        return;
      case 'add':
      case 'insert':
        if (targetsCurrency) throw new Error(`${prefix} 不得重新创建或覆盖世界币`);
        setAtPointer(next, path, entry.value, true);
        return;
      case 'inc':
      case 'increment':
      case 'delta': {
        const current = _.get(next, path);
        const delta = typeof entry.value === 'number' ? entry.value : Number(entry.value);
        if (typeof current !== 'number' || !Number.isFinite(delta)) {
          throw new Error(`${prefix} 的 delta 目标和增量必须都是有限数字`);
        }
        if (targetsCurrency && delta <= 0) {
          throw new Error(`${prefix} 不得减少或清零世界币；消费与模块升级只由前端扣款`);
        }
        setAtPointer(next, path, current + delta, false);
        return;
      }
      case 'delete':
      case 'remove':
        if (targetsCurrency) throw new Error(`${prefix} 不得删除世界币`);
        removeAtPointer(next, path);
        return;
      default:
        throw new Error(`${prefix} 使用了不支持的操作 ${operation}`);
    }
  });
  const worldChanged = next.当前世界.名称 !== statData.当前世界.名称;
  if (worldChanged) {
    next.当前世界.特殊规则 = _.pickBy(
      next.当前世界.特殊规则,
      (description, name) => statData.当前世界.特殊规则[name] !== description,
    );
    next.当前世界.近期事件 = _.pickBy(
      next.当前世界.近期事件,
      (description, name) => statData.当前世界.近期事件[name] !== description,
    );
    if (_.isEqual(next.当前世界.异常事件, statData.当前世界.异常事件)) next.当前世界.异常事件 = null;
  }
  const parsed = Schema.parse(next);
  if (worldChanged && parsed.当前世界.名称 !== '零号中转站') {
    if (Object.keys(parsed.当前世界.特殊规则).length < 2) {
      throw new Error('世界切换后必须生成至少 2 条全新的特殊规则，不能沿用上一世界规则');
    }
    if (
      parsed.当前世界.当前任务.名称 === statData.当前世界.当前任务.名称 &&
      parsed.当前世界.当前任务.描述 === statData.当前世界.当前任务.描述
    ) {
      throw new Error('世界切换后仍沿用了上一世界任务，请生成与新世界对应的新任务');
    }
  }
  return parsed;
}

async function parseCandidateMessage(messageId: number, oldData: Mvu.MvuData, candidate: string): Promise<Mvu.MvuData> {
  const previousStatData = Schema.parse(_.get(oldData, 'stat_data'));
  const operations = readJsonPatch(candidate);
  const parsedStatData = applyJsonPatch(previousStatData, operations);
  if (operations.length > 0 && _.isEqual(previousStatData, parsedStatData)) {
    throw new Error('辅助 API 返回了更新操作，但执行后变量没有发生变化');
  }
  const parsed = klona(oldData);
  _.set(parsed, 'stat_data', parsedStatData);
  console.info(
    `[世界快穿模拟器][辅助API] 第 ${messageId} 层已直接执行 ${operations.length} 条 JSONPatch，并通过 Schema 校验`,
  );
  return parsed;
}

function delay(milliseconds: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, milliseconds));
}

function mvuStatDataMatches(messageId: number, expectedData: Mvu.MvuData): boolean {
  const expected = Schema.parse(_.get(expectedData, 'stat_data'));
  const actual = Schema.safeParse(_.get(getVariables({ type: 'message', message_id: messageId }), 'stat_data'));
  return actual.success && _.isEqual(actual.data, expected);
}

function replaceUnderlyingStatData(messageId: number, data: Mvu.MvuData): void {
  const target = { type: 'message', message_id: messageId } as const;
  const hasStatData = _.has(data, 'stat_data');
  const statData = hasStatData ? Schema.parse(_.get(data, 'stat_data')) : undefined;
  updateVariablesWith(variables => {
    const next = klona(variables);
    if (hasStatData) _.set(next, 'stat_data', statData);
    else _.unset(next, 'stat_data');
    return next;
  }, target);
}

async function replaceAndVerifyMvuData(messageId: number, parsedData: Mvu.MvuData): Promise<void> {
  const target = { type: 'message', message_id: messageId } as const;
  const verificationDelays = [80, 220];
  for (let attempt = 0; attempt < verificationDelays.length; attempt++) {
    try {
      await Mvu.replaceMvuData(klona(parsedData), target);
    } catch (error) {
      console.warn(`[世界快穿模拟器][辅助API] 第 ${messageId} 层 MVU 写入接口失败，改用底层变量接口`, error);
    }
    replaceUnderlyingStatData(messageId, parsedData);
    await delay(verificationDelays[attempt]);
    if (mvuStatDataMatches(messageId, parsedData)) return;
    console.warn(`[世界快穿模拟器][辅助API] 第 ${messageId} 层变量写入校验未通过，准备重试`);
  }
  throw new Error(`第 ${messageId} 层的 MVU 变量写入后校验失败`);
}

async function commitCandidate(
  messageId: number,
  originalMessage: string,
  candidateMessage: string,
  originalData: Mvu.MvuData,
  parsedData: Mvu.MvuData,
): Promise<void> {
  let messageChanged = false;
  try {
    // 先写入楼层正文数据，再把解析后的变量作为最后一次写入。
    // 不重绘酒馆原生楼层：重绘会替换整层 DOM，删除其他脚本追加的临时内容。
    await setChatMessages([{ message_id: messageId, message: candidateMessage }], {
      refresh: 'none',
    });
    messageChanged = true;
    if (readAssistantMessage(messageId).message !== candidateMessage) {
      throw new Error(`第 ${messageId} 层的变量更新正文写入后校验失败`);
    }
    await replaceAndVerifyMvuData(messageId, parsedData);
  } catch (error) {
    try {
      if (messageChanged) {
        await setChatMessages([{ message_id: messageId, message: originalMessage }], {
          refresh: 'none',
        });
      }
      try {
        await Mvu.replaceMvuData(klona(originalData), { type: 'message', message_id: messageId });
      } catch (mvuRollbackError) {
        console.warn('[世界快穿模拟器][辅助API] MVU 回滚接口失败，继续使用底层变量接口回滚', mvuRollbackError);
      }
      replaceUnderlyingStatData(messageId, originalData);
    } catch (rollbackError) {
      console.error('[世界快穿模拟器][辅助API] 提交失败且消息或变量回滚失败', rollbackError);
    }
    throw error;
  }
  console.info(`[世界快穿模拟器][辅助API] 第 ${messageId} 层正文与 MVU 变量均已写入并通过校验`);
}

async function runForMessage(
  messageId: number,
  manual: boolean,
): Promise<'success' | 'failed' | 'stopped' | 'skipped'> {
  const store = useAssistantApiStore();
  if (store.busy) {
    if (manual) toastr.info('辅助 API 正在处理中，请稍候');
    return 'skipped';
  }
  if (store.variableUpdateMode !== 'extra_api') {
    if (manual) toastr.warning('当前没有启用辅助 API 更新模式');
    return 'skipped';
  }
  const apis = store.runnableApis();
  if (!apis.length) {
    if (manual) toastr.warning('请先配置并保存至少一个辅助 API');
    return 'skipped';
  }

  const runId = `world-fast-travel-assistant-${messageId}-${Date.now()}`;
  const sendButtonWasDisabled = nativeSendButtonDisabled();
  store.beginRun(messageId, runId);
  const errors: string[] = [];
  try {
    if (!sendButtonWasDisabled) SillyTavern.deactivateSendButtons();
    eventEmit('assistant_api_started', { source: 'assistant_api', message_id: messageId });

    const target = readAssistantMessage(messageId);
    const narrative = extractNarrative(target.message);
    if (!narrative) throw new Error('目标 AI 楼层没有可用于变量更新的剧情正文');

    const chatId = currentChatId();
    const originalMessage = target.message;
    ensureTargetUnchanged(messageId, chatId, originalMessage);
    const directData = klona(Mvu.getMvuData({ type: 'message', message_id: messageId }));
    const oldData = readBaseMvuData(messageId);
    const rollbackData = _.isEmpty(_.get(directData, 'stat_data')) ? oldData : directData;
    const statData = Schema.parse(_.get(oldData, 'stat_data'));
    const previousUserMessage = readPreviousUserMessage(messageId);
    const prompts = await readPromptBundle();
    if (store.stopRequested) throw new AssistantApiStoppedError('用户停止了辅助 API');

    for (const [index, api] of apis.entries()) {
      if (store.stopRequested) throw new AssistantApiStoppedError('用户停止了辅助 API');
      const generationId = `${runId}-${index}`;
      store.activeGenerationId = generationId;
      try {
        console.info(`[世界快穿模拟器][辅助API] 调用第 ${index + 1}/${apis.length} 个 API：${api.model}`);
        const updateBlock = await requestUpdate(api, prompts, statData, previousUserMessage, narrative, generationId);
        if (store.stopRequested) throw new AssistantApiStoppedError('用户停止了辅助 API');
        ensureTargetUnchanged(messageId, chatId, originalMessage);
        const candidateMessage = mergeUpdateBlock(originalMessage, updateBlock);
        const parsedData = await parseCandidateMessage(messageId, oldData, candidateMessage);
        ensureTargetUnchanged(messageId, chatId, originalMessage);
        await commitCandidate(messageId, originalMessage, candidateMessage, rollbackData, parsedData);
        store.finishRun('success');
        eventEmit('assistant_api_variable_updated', {
          source: 'assistant_api',
          message_id: messageId,
          filteredUpdate: updateBlock,
        });
        eventEmit('assistant_api_completed', { source: 'assistant_api', status: 'success', message_id: messageId });
        toastr.success('辅助 API 已完成变量更新');
        return 'success';
      } catch (error) {
        if (error instanceof AssistantApiStoppedError || store.stopRequested) throw error;
        if (error instanceof TargetMessageChangedError) throw error;
        const message = error instanceof Error ? error.message : String(error);
        errors.push(`API ${index + 1}：${message}`);
        console.warn(`[世界快穿模拟器][辅助API] 第 ${index + 1} 个 API 失败，准备尝试下一个`, error);
      }
    }
    throw new Error(errors.join('；') || '所有辅助 API 均未返回有效变量更新');
  } catch (error) {
    const stopped = error instanceof AssistantApiStoppedError || store.stopRequested;
    const message = error instanceof Error ? error.message : String(error);
    store.finishRun(stopped ? 'stopped' : 'failed', stopped ? '' : message);
    eventEmit('assistant_api_completed', {
      source: 'assistant_api',
      status: stopped ? 'stopped' : 'failed',
      reason: stopped ? 'user_stopped' : 'api_error',
      message_id: messageId,
    });
    if (stopped) {
      toastr.info('已停止辅助 API 变量更新');
      return 'stopped';
    }
    console.error('[世界快穿模拟器][辅助API] 变量更新失败', error);
    toastr.error(`辅助 API 更新失败：${message}`);
    return 'failed';
  } finally {
    if (!sendButtonWasDisabled) SillyTavern.activateSendButtons();
  }
}

function clearPendingSession() {
  pendingSession = null;
  if (pendingTimer !== null) clearTimeout(pendingTimer);
  pendingTimer = null;
}

function schedulePendingRun(delay = 80) {
  if (!pendingSession || pendingTimer !== null) return;
  pendingTimer = setTimeout(() => {
    pendingTimer = null;
    if (!pendingSession) return;
    if (runtimeIsGenerating()) {
      schedulePendingRun(120);
      return;
    }
    const session = pendingSession;
    pendingSession = null;
    if (session.chatId !== currentChatId()) return;
    void runForMessage(session.messageId, false);
  }, delay);
}

export function startAssistantApiRunner(): () => void {
  if (disposeRunner) return disposeRunner;
  const store = useAssistantApiStore();
  const listeners: EventOnReturn[] = [];
  listeners.push(
    eventOn(tavern_events.MESSAGE_RECEIVED, (messageId, type) => {
      if (store.variableUpdateMode !== 'extra_api' || !ALLOWED_MESSAGE_TYPES.has(type) || store.busy) return;
      pendingSession = { messageId, chatId: currentChatId() };
      schedulePendingRun(runtimeIsGenerating() ? 250 : 80);
    }),
    eventOn(tavern_events.GENERATION_ENDED, messageId => {
      if (store.busy || !pendingSession || pendingSession.messageId !== messageId) return;
      schedulePendingRun(0);
    }),
    eventOn(tavern_events.GENERATION_STOPPED, () => {
      if (store.busy) {
        store.stopRequested = true;
      } else {
        clearPendingSession();
      }
    }),
  );
  void store.reconcileWorldbookMode();

  disposeRunner = () => {
    clearPendingSession();
    listeners.forEach(listener => listener.stop());
    if (store.busy) stopAssistantApiGeneration();
    disposeRunner = null;
  };
  console.info('[世界快穿模拟器][辅助API] 变量更新 Runner 已启动');
  return disposeRunner;
}

export async function refreshLatestAssistantVariables(): Promise<boolean> {
  clearPendingSession();
  const latestMessageId = getLastMessageId();
  const latestMessage = getChatMessages(latestMessageId, { role: 'all' })[0];
  if (!latestMessage || latestMessage.role !== 'assistant') {
    toastr.warning('最新楼层不是完整的 AI 回复，暂时不能刷新变量');
    return false;
  }
  return (await runForMessage(latestMessage.message_id, true)) === 'success';
}

export function stopAssistantApiGeneration(): boolean {
  const store = useAssistantApiStore();
  if (!store.busy) return false;
  store.stopRequested = true;
  const generationId = store.activeGenerationId;
  const stoppedById = generationId ? stopGenerationById(generationId) : false;
  const stoppedAll = stoppedById ? false : stopAllGeneration();
  console.info(`[世界快穿模拟器][辅助API] 已请求停止辅助生成，按ID停止：${stoppedById}，全局停止：${stoppedAll}`);
  return true;
}
