const WorldAnomalySchema = z
    .object({
    名称: z.string(),
    描述: z.string(),
    危险度: z.enum(['轻微', '显著', '严重', '灾变']),
    状态: z.enum(['潜伏', '进行中', '已解决', '已失控']),
    目标: z.string(),
    结果: z.string().prefault('尚无定论'),
    奖励: z.object({
        世界币: z.coerce.number().transform(value => Math.max(0, Math.trunc(value))),
        能量: z.coerce.number().transform(value => _.clamp(Math.trunc(value), 0, 20)),
        稳定度: z.coerce.number().transform(value => _.clamp(Math.trunc(value), 0, 20)),
    }),
    $奖励已结算: z.boolean().prefault(false),
})
    .overwrite(anomaly => {
    const rewardRanges = {
        轻微: { 世界币: [15, 30], 能量: [3, 5], 稳定度: [2, 5] },
        显著: { 世界币: [30, 60], 能量: [5, 8], 稳定度: [5, 8] },
        严重: { 世界币: [60, 100], 能量: [8, 12], 稳定度: [8, 12] },
        灾变: { 世界币: [100, 160], 能量: [12, 15], 稳定度: [12, 20] },
    };
    const ranges = rewardRanges[anomaly.危险度];
    return {
        ...anomaly,
        奖励: {
            世界币: _.clamp(anomaly.奖励.世界币, ranges.世界币[0], ranges.世界币[1]),
            能量: _.clamp(anomaly.奖励.能量, ranges.能量[0], ranges.能量[1]),
            稳定度: _.clamp(anomaly.奖励.稳定度, ranges.稳定度[0], ranges.稳定度[1]),
        },
    };
});
const ShuttleModulesSchema = z
    .object({
    能量回收: z.coerce
        .number()
        .transform(value => _.clamp(Math.trunc(value), 0, 3))
        .prefault(0),
    稳定锚定: z.coerce
        .number()
        .transform(value => _.clamp(Math.trunc(value), 0, 3))
        .prefault(0),
    身份拟态: z.coerce
        .number()
        .transform(value => _.clamp(Math.trunc(value), 0, 3))
        .prefault(0),
    任务演算: z.coerce
        .number()
        .transform(value => _.clamp(Math.trunc(value), 0, 3))
        .optional(),
    记忆锚定: z.coerce
        .number()
        .transform(value => _.clamp(Math.trunc(value), 0, 3))
        .optional(),
})
    .prefault({})
    .transform(({ 记忆锚定, 任务演算, ...modules }) => ({
    ...modules,
    任务演算: 任务演算 ?? 记忆锚定 ?? 0,
}));
