const STORAGE_KEY = 'tavern_helper_settings_世界快穿模拟器';
const GOOGLE_API_URL = 'https://generativelanguage.googleapis.com/v1beta/models';
const StoredApiSchema = z
    .object({
    id: z.string().optional(),
    apiurl: z.string().prefault(''),
    key: z.string().prefault(''),
    model: z.string().prefault(''),
    source: z.enum(['openai_compatible', 'google']).prefault('openai_compatible'),
    availableModels: z.array(z.string()).prefault([]),
    sendPreset: z.boolean().prefault(false),
    collapsed: z.boolean().prefault(false),
    saved: z.boolean().prefault(false),
})
    .prefault({});
const StoredSettingsSchema = z
    .object({
    variableUpdateMode: z.enum(['with_main_api', 'extra_api']).prefault('with_main_api'),
    customApis: z.array(StoredApiSchema).optional(),
    customApi: StoredApiSchema.optional(),
})
    .prefault({});
function createApiId() {
    return `assistant-api-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function createEmptyApi() {
    return {
        id: createApiId(),
        apiurl: '',
        key: '',
        model: '',
        source: 'openai_compatible',
        availableModels: [],
        sendPreset: false,
        collapsed: false,
        saved: false,
    };
}
function normalizeApi(input, legacy = false) {
    return {
        id: input.id || createApiId(),
        apiurl: input.source === 'google' ? GOOGLE_API_URL : input.apiurl,
        key: input.key,
        model: input.model,
        source: input.source,
        availableModels: input.availableModels,
        sendPreset: input.sendPreset,
        collapsed: input.collapsed,
        saved: legacy || input.saved,
    };
}
function getStorage() {
    try {
        return window.parent?.localStorage ?? window.localStorage;
    }
    catch {
        return window.localStorage;
    }
}
function loadStoredSettings() {
    try {
        const raw = getStorage().getItem(STORAGE_KEY);
        const settings = StoredSettingsSchema.parse(raw ? JSON.parse(raw) : {});
        const customApis = settings.customApis?.length
            ? settings.customApis.map(api => normalizeApi(api))
            : settings.customApi && (settings.customApi.apiurl || settings.customApi.key || settings.customApi.model)
                ? [normalizeApi(settings.customApi, true)]
                : [createEmptyApi()];
        return { variableUpdateMode: settings.variableUpdateMode, customApis };
    }
    catch (error) {
        console.warn('[世界快穿模拟器][辅助API] 读取设置失败，已回退默认值', error);
        return { variableUpdateMode: 'with_main_api', customApis: [createEmptyApi()] };
    }
}
function validateApi(api) {
    if (!api.apiurl.trim())
        return '请填写 API 地址';
    if (!api.key.trim())
        return '请填写 API Key';
    if (!api.model.trim())
        return '请选择或填写模型';
    return null;
}
export const useAssistantApiStore = defineStore('world-fast-travel-assistant-api', () => {
    const stored = loadStoredSettings();
    const variableUpdateMode = ref(stored.variableUpdateMode);
    const customApis = ref(stored.customApis);
    const busy = ref(false);
    const activeMessageId = ref(null);
    const activeGenerationId = ref(null);
    const stopRequested = ref(false);
    const lastStatus = ref('idle');
    const lastError = ref('');
    const lastSuccessAt = ref('');
    function persistSettings() {
        try {
            getStorage().setItem(STORAGE_KEY, JSON.stringify({
                variableUpdateMode: variableUpdateMode.value,
                customApis: customApis.value,
                customApi: customApis.value[0],
            }));
            return true;
        }
        catch (error) {
            console.error('[世界快穿模拟器][辅助API] 保存设置失败', error);
            return false;
        }
    }
    function runnableApis() {
        return customApis.value.filter(api => api.saved && validateApi(api) === null);
    }
    function validateAllApis() {
        const configured = customApis.value.filter(api => api.apiurl || api.key || api.model);
        if (!configured.length)
            return '请至少配置并保存一个辅助 API';
        for (const [index, api] of configured.entries()) {
            const error = validateApi(api);
            if (error)
                return `第 ${index + 1} 个辅助 API 配置不完整：${error}`;
            if (!api.saved)
                return `第 ${index + 1} 个辅助 API 尚未保存`;
        }
        return null;
    }
    function addApi() {
        customApis.value.push(createEmptyApi());
    }
    function removeApi(index) {
        if (customApis.value.length <= 1)
            return;
        customApis.value.splice(index, 1);
        persistSettings();
    }
    function moveApi(index, offset) {
        const target = index + offset;
        if (target < 0 || target >= customApis.value.length)
            return;
        const [api] = customApis.value.splice(index, 1);
        customApis.value.splice(target, 0, api);
        persistSettings();
    }
    function toggleApiCollapsed(index) {
        const api = customApis.value[index];
        if (!api)
            return;
        api.collapsed = !api.collapsed;
        persistSettings();
    }
    function markApiDirty(apiId) {
        const api = customApis.value.find(item => item.id === apiId);
        if (api)
            api.saved = false;
    }
    function changeApiSource(apiId, source) {
        const api = customApis.value.find(item => item.id === apiId);
        if (!api)
            return;
        api.source = source;
        api.apiurl = source === 'google' ? GOOGLE_API_URL : '';
        api.model = '';
        api.availableModels = [];
        api.saved = false;
        api.collapsed = false;
    }
    function saveApi(index) {
        const api = customApis.value[index];
        if (!api)
            return '目标 API 配置不存在';
        const error = validateApi(api);
        if (error)
            return error;
        api.apiurl = api.apiurl.trim();
        api.key = api.key.trim();
        api.model = api.model.trim();
        api.saved = true;
        api.collapsed = true;
        return persistSettings() ? null : '保存失败，请检查浏览器存储权限';
    }
    async function fetchAvailableModels(index) {
        const api = customApis.value[index];
        if (!api)
            throw new Error('目标 API 配置不存在');
        if (!api.apiurl.trim())
            throw new Error('请先填写 API 地址');
        if (!api.key.trim())
            throw new Error('请先填写 API Key');
        let models;
        if (api.source === 'google') {
            const response = await fetch(`${api.apiurl}?key=${encodeURIComponent(api.key)}`);
            if (!response.ok)
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            const payload = (await response.json());
            models = (payload.models ?? [])
                .filter(model => model.supportedGenerationMethods?.includes('generateContent'))
                .map(model => model.name?.replace(/^models\//, '') ?? '')
                .filter(Boolean);
        }
        else {
            const baseUrl = api.apiurl.replace(/\/chat\/completions\/?$/i, '').replace(/\/$/, '');
            const response = await fetch(`${baseUrl}/models`, { headers: { Authorization: `Bearer ${api.key}` } });
            if (!response.ok)
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            const payload = (await response.json());
            models = (payload.data ?? []).map(model => model.id ?? '').filter(Boolean);
        }
        const uniqueModels = _.uniq(models).sort();
        if (!uniqueModels.length)
            throw new Error('没有获取到可用模型');
        api.availableModels = uniqueModels;
        api.saved = false;
        return uniqueModels;
    }
    async function syncWorldbookMode(mode) {
        if (busy.value)
            throw new Error('辅助 API 正在运行，暂时不能切换模式');
        if (mode === 'extra_api') {
            const validationError = validateAllApis();
            if (validationError)
                throw new Error(validationError);
        }
        const worldbookName = getCharWorldbookNames('current').primary;
        if (!worldbookName)
            throw new Error('当前角色卡没有绑定主世界书');
        const entries = await getWorldbook(worldbookName);
        const rules = entries.find(entry => entry.name === '[mvu_update]变量更新规则');
        const format = entries.find(entry => entry.name === '[mvu_update]变量输出格式');
        const noUpdate = entries.find(entry => entry.name === '[mvu_update]不更新变量');
        if (!rules || !format || !noUpdate)
            throw new Error('世界书缺少辅助 API 模式所需的变量条目');
        const useMainApi = mode === 'with_main_api';
        await updateWorldbookWith(worldbookName, worldbook => worldbook.map(entry => {
            if (entry.uid === rules.uid || entry.uid === format.uid)
                return { ...entry, enabled: useMainApi };
            if (entry.uid === noUpdate.uid)
                return { ...entry, enabled: !useMainApi };
            return entry;
        }));
        variableUpdateMode.value = mode;
        if (!persistSettings())
            throw new Error('模式已切换，但本地设置保存失败');
    }
    async function reconcileWorldbookMode() {
        try {
            await syncWorldbookMode(variableUpdateMode.value);
        }
        catch (error) {
            console.warn('[世界快穿模拟器][辅助API] 初始化模式同步失败', error);
            if (variableUpdateMode.value === 'extra_api') {
                variableUpdateMode.value = 'with_main_api';
                persistSettings();
                try {
                    await syncWorldbookMode('with_main_api');
                }
                catch (fallbackError) {
                    console.error('[世界快穿模拟器][辅助API] 回退主模型模式失败', fallbackError);
                }
            }
        }
    }
    function beginRun(messageId, generationId) {
        busy.value = true;
        activeMessageId.value = messageId;
        activeGenerationId.value = generationId;
        stopRequested.value = false;
        lastStatus.value = 'running';
        lastError.value = '';
    }
    function finishRun(status, error = '') {
        busy.value = false;
        activeMessageId.value = null;
        activeGenerationId.value = null;
        stopRequested.value = false;
        lastStatus.value = status;
        lastError.value = error;
        if (status === 'success')
            lastSuccessAt.value = new Date().toLocaleTimeString();
    }
    return {
        variableUpdateMode,
        customApis,
        busy,
        activeMessageId,
        activeGenerationId,
        stopRequested,
        lastStatus,
        lastError,
        lastSuccessAt,
        runnableApis,
        validateAllApis,
        addApi,
        removeApi,
        moveApi,
        toggleApiCollapsed,
        markApiDirty,
        changeApiSource,
        saveApi,
        fetchAvailableModels,
        syncWorldbookMode,
        reconcileWorldbookMode,
        beginRun,
        finishRun,
    };
});
